def find_path(graph, start, goal):
    if start not in graph or goal not in graph:
        return None
    path = []
    visited = set()
    
    while start != goal:
        if not path:
            path.append(start)
            visited.add(start)
        
        neighbors = graph[start]
        next_node = None
        if not neighbors:
            return None
        
        for neighbor in neighbors:
            if neighbor not in visited:
                if neighbor in path:
                    continue
                if neighbor == goal:
                    next_node = neighbor
                    break
                path.append(neighbor)
                visited.add(neighbor)
                break
        
        if not next_node:
            return None
        
        path.append(next_node)
        start = next_node
    
    path.append(goal)
    return path
    
