def find_path(graph, start, goal): 
    queue = [(start, [start])]   
    while queue: 
        (vertex, path) = queue.pop(0)   
        for next in set(graph[vertex]) - set(path): 
            if next == goal: 
                return path + [next] 
            else: 
                queue.append((next, path + [next]))   
    return None

